class Solution {
public:
    long long nthSmallest(long long n, int k) {
        long long c[51][51] = {};
        for (int i = 0; i <= 50; ++i) {
            c[i][0] = c[i][i] = 1;
            for (int j = 1; j < i; ++j)
                c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
        }
        long long answer = 0;
        for (int bit = 49; bit >= 0; --bit) {
            long long without = (k >= 0 && k <= bit) ? c[bit][k] : 0;
            if (n > without) {
                answer |= 1LL << bit;
                n -= without;
                --k;
            }
        }
        return answer;
    }
};
